      const [x,y]=buildingCenter(building);
      const candidates=state.cells.filter(cell=>cell.buildable).sort((a,b)=>Number(b.r===building.r)-Number(a.r===building.r)||Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y));
